module find_good_nodes(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [55:0] edge_data,\n    input [27:0] edge_colors,\n    input [2:0] valid_edges,\n    output reg [3:0] good_nodes [0:7],\n    output reg [3:0] count,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] BUILD_GRAPH= 3'd1;\n    localparam [2:0] CHECK_NODE = 3'd2;\n    localparam [2:0] BFS        = 3'd3;\n    localparam [2:0] NEXT_NODE  = 3'd4;\n    localparam [2:0] COMPLETE   = 3'd5;\n    reg [2:0] state;\n\n    // Adjacency Matrix (8x8)\n    reg [3:0] adj_matrix [0:7][0:7];\n\n    // BFS Variables\n    reg [3:0] current_node;\n    reg [3:0] node_queue [0:7];\n    reg [2:0] q_head;\n    reg [2:0] q_tail;\n    reg visited [0:7];\n    reg [3:0] parents [0:7];\n    reg [3:0] last_color [0:7];\n    reg violation;\n\n    // Counters\n    reg [9:0] cycle_counter;\n    reg [3:0] node_index;\n    reg [2:0] edge_index;\n    reg [3:0] i, j;\n\n    // Good Nodes Storage\n    reg [7:0] is_good;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            done <= 1'b0;\n            count <= 4'd0;\n            violation <= 1'b0;\n            cycle_counter <= 10'd0;\n            node_index <= 4'd0;\n            edge_index <= 3'd0;\n            is_good <= 8'd0;\n            q_head <= 3'd0;\n            q_tail <= 3'd0;\n            current_node <= 4'd0;\n\n            // Initialize adjacency matrix\n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    adj_matrix[i][j] <= 4'd0;\n                end\n            end\n\n            // Initialize BFS arrays\n            for (i = 0; i < 8; i = i + 1) begin\n                node_queue[i] <= 4'd0;\n                visited[i] <= 1'b0;\n                parents[i] <= 4'd0;\n                last_color[i] <= 4'd0;\n            end\n\n            // Initialize good_nodes array\n            for (i = 0; i < 8; i = i + 1) begin\n                good_nodes[i] <= 4'd0;\n            end\n        end else begin\n            cycle_counter <= cycle_counter + 1'b1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= BUILD_GRAPH;\n                        edge_index <= 3'd0;\n                        for (i = 0; i < 8; i = i + 1) begin\n                            for (j = 0; j < 8; j = j + 1) begin\n                                adj_matrix[i][j] <= 4'd0;\n                            end\n                        end\n                    end\n                end\n\n                BUILD_GRAPH: begin\n                    if (edge_index < valid_edges) begin\n                        // Extract edge from edge_data and edge_colors\n                        adj_matrix[edge_data[edge_index*8 +:4]][edge_data[edge_index*8 +4 +:4]] <= edge_colors[edge_index*4 +:4];\n                        adj_matrix[edge_data[edge_index*8 +4 +:4]][edge_data[edge_index*8 +:4]] <= edge_colors[edge_index*4 +:4];\n                        edge_index <= edge_index + 1;\n                    end else begin\n                        state <= CHECK_NODE;\n                        node_index <= 4'd0;\n                        is_good <= 8'd0;\n                    end\n                end\n\n                CHECK_NODE: begin\n                    // BFS initialization\n                    for (i = 0; i < 8; i = i + 1) begin\n                        visited[i] <= 1'b0;\n                    end\n                    q_head <= 3'd0;\n                    q_tail <= 3'd0;\n                    node_queue[q_tail] <= node_index;\n                    q_tail <= q_tail + 1;\n                    visited[node_index] <= 1'b1;\n                    parents[node_index] <= node_index;\n                    last_color[node_index] <= 4'd0;\n                    violation <= 1'b0;\n                    state <= BFS;\n                end\n\n                BFS: begin\n                    if (q_head != q_tail && !violation) begin\n                        current_node <= node_queue[q_head];\n                        q_head <= q_head + 1;\n\n                        for (i = 0; i < 8; i = i +1) begin\n                            if (i != current_node && adj_matrix[current_node][i] != 4'd0 && !visited[i]) begin\n                                if (current_node != node_index && adj_matrix[current_node][i] == last_color[current_node]) begin\n                                    violation <= 1'b1;\n                                end else begin\n                                    visited[i] <= 1'b1;\n                                    parents[i] <= current_node;\n                                    last_color[i] <= adj_matrix[current_node][i];\n                                    node_queue[q_tail] <= i;\n                                    q_tail <= q_tail + 1;\n                                end\n                            end\n                        end\n                    end else if (q_head == q_tail) begin\n                        // BFS completed without violations\n                        is_good[node_index] <= 1'b1;\n                        state <= NEXT_NODE;\n                    end else if (violation) begin\n                        // Violation found\n                        is_good[node_index] <= 1'b0;\n                        state <= NEXT_NODE;\n                    end\n                    if (cycle_counter >= 10'd1000) begin\n                        state <= COMPLETE;\n                    end\n                end\n\n                NEXT_NODE: begin\n                    if (node_index < n - 1) begin\n                        node_index <= node_index + 1;\n                        state <= CHECK_NODE;\n                    end else begin\n                        state <= COMPLETE;\n                    end\n                end\n\n                COMPLETE: begin\n                    // Populate good_nodes array with sorted indices\n                    reg [3:0] pos = 4'd0;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (i < n && is_good[i]) begin\n                            good_nodes[pos] <= i;\n                            pos = pos + 1;\n                        end\n                    end\n                    count <= pos;\n                    // Zero out remaining positions\n                    for (i = pos; i < 8; i = i + 1) begin\n                        good_nodes[i] <= 4'd0;\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule